if (!remoteJid.endsWith('@g.us')) return sendTrackedMessage(sock, remoteJid, "This command can only be used in groups.");
const contextInfo = msg.message?.extendedTextMessage?.contextInfo;
const targetUser = contextInfo?.participant || (contextInfo?.mentionedJid && contextInfo.mentionedJid[0]);

if (!targetUser) return sendTrackedMessage(sock, remoteJid, "⚠️ Please reply to a user's message or tag them to warn.");

const fs = require('fs');
const path = require('path');
const warnsFile = path.resolve(process.cwd(), 'warns.json');

let warns = {};
if (fs.existsSync(warnsFile)) {
    warns = JSON.parse(fs.readFileSync(warnsFile, 'utf8'));
}
if (!warns[remoteJid]) warns[remoteJid] = {};

warns[remoteJid][targetUser] = (warns[remoteJid][targetUser] || 0) + 1;
fs.writeFileSync(warnsFile, JSON.stringify(warns, null, 2));

const warnCount = warns[remoteJid][targetUser];
if (warnCount >= 3) {
    await sock.sendMessage(remoteJid, { text: `🚨 @${targetUser.split('@')[0]} has reached 3 warnings and is being permanently removed from the group!`, mentions: [targetUser] });
    try {
        await sock.groupParticipantsUpdate(remoteJid, [targetUser], 'remove');
    } catch (e) {
        await sock.sendMessage(remoteJid, { text: "❌ I don't have Admin permissions to remove them!" });
    }
    warns[remoteJid][targetUser] = 0;
    fs.writeFileSync(warnsFile, JSON.stringify(warns, null, 2));
} else {
    await sock.sendMessage(remoteJid, { text: `⚠️ @${targetUser.split('@')[0]} you have been warned! (${warnCount}/3) Behave or you will be kicked.`, mentions: [targetUser] });
}

