const contextInfo = msg.message?.extendedTextMessage?.contextInfo;
const isSetting = argumentName;

const fs = require('fs');
const path = require('path');
const configPath = path.resolve(process.cwd(), 'antibc.json');

let config = { message: 'remove me from broadcast' };
if (fs.existsSync(configPath)) {
    config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
}

// Intercepting an actual broadcast message via the script engine 
// (WXATA automatically forwards context if we bypass the prefix inside our engine logic if rigged right, 
// but since WXATA requires a prefix to trigger scripts, let's actually just register this as a config setter)
if (isSetting && isSetting !== "on" && isSetting !== "off") {
    // If user passed a full string (argumentName only captures first word due to regex in index.ts, so we read raw message text)
    const rawText = msg.message?.conversation || msg.message?.extendedTextMessage?.text || "";
    const newMsg = rawText.substring(rawText.indexOf(argumentName)); // Grab everything after the command

    config.message = newMsg;
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
    return await sendTrackedMessage(sock, remoteJid, `_new var ANTI_BROADCAST_MSG added as: ${newMsg}_`);
} else if (isSetting === "off") {
    config.enabled = false;
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
    return await sendTrackedMessage(sock, remoteJid, `_Anti-Broadcast disabled_`);
} else if (isSetting === "on") {
    config.enabled = true;
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
    return await sendTrackedMessage(sock, remoteJid, `_Anti-Broadcast enabled_`);
}

await sendTrackedMessage(sock, remoteJid, `*Example :* ${botInfo.prefix}antibc dont send broadcast please!`);

