const fs = require('fs');
const path = require('path');
const varsFile = path.resolve(process.cwd(), 'vars.json');

const isSudo = botInfo.permissions.numbers?.includes(remoteJid.split('@')[0]) || msg.key?.fromMe;
if (!isSudo) return sendTrackedMessage(sock, remoteJid, '❌ Permission Denied. Sudo only.');

let configVars = {};
if (fs.existsSync(varsFile)) {
  try { configVars = JSON.parse(fs.readFileSync(varsFile, 'utf8')); } catch(e) {}
}

const rawText = msg.message?.conversation || msg.message?.extendedTextMessage?.text || '';
const args = rawText.trim().split(/\s+/).slice(1);

// READ — show system vars + custom vars
if (args.length === 0) {
  const sudoList = botInfo.permissions.numbers.length ? botInfo.permissions.numbers.map(n => '+' + n).join(', ') : 'none';
  const chatList = botInfo.permissions.chats.length ? botInfo.permissions.chats.join(', ') : 'none';
  let text = '⚙️ *WXATA System Vars*\n\n';
  text += `🔹 *PREFIX*: ${botInfo.prefix}\n`;
  text += `🔹 *ROOT*: ${botInfo.root?.target || 'self'}\n`;
  text += `🔹 *ALLOW_ALL*: ${botInfo.permissions.allowAll}\n`;
  text += `🔹 *SUDO_NUMBERS*: ${sudoList}\n`;
  text += `🔹 *PERMITTED_CHATS*: ${chatList}\n`;
  if (Object.keys(configVars).length) {
    text += '\n📦 *Custom Vars*\n';
    for (const [k, v] of Object.entries(configVars)) {
      text += `🔸 *${k}*: ${v}\n`;
    }
  } else {
    text += '\n_No custom vars set. Use +vars set KEY value_';
  }
  return sendTrackedMessage(sock, remoteJid, text);
}

// SET
if (args[0] === 'set' && args.length >= 3) {
  const key = args[1].toUpperCase();
  const value = args.slice(2).join(' ');
  // Handle system keys that map to botInfo
  if (key === 'PREFIX') {
    const { updateBotInfo } = require('./index'); // not available in sandbox — use direct file write
    const biPath = path.resolve(process.cwd(), 'botinfo.json');
    const bi = JSON.parse(fs.readFileSync(biPath, 'utf8'));
    bi.prefix = value;
    fs.writeFileSync(biPath, JSON.stringify(bi, null, 2));
    return sendTrackedMessage(sock, remoteJid, `✅ PREFIX updated to: *${value}*\n_Restart bot to apply._`);
  }
  if (key === 'SUDO' || key === 'SUDO_NUMBER') {
    const num = value.replace(/\D/g, '');
    const biPath = path.resolve(process.cwd(), 'botinfo.json');
    const bi = JSON.parse(fs.readFileSync(biPath, 'utf8'));
    if (!bi.permissions.numbers.includes(num)) bi.permissions.numbers.push(num);
    fs.writeFileSync(biPath, JSON.stringify(bi, null, 2));
    return sendTrackedMessage(sock, remoteJid, `✅ *+${num}* added as sudo number.`);
  }
  configVars[key] = value;
  fs.writeFileSync(varsFile, JSON.stringify(configVars, null, 2));
  return sendTrackedMessage(sock, remoteJid, `✅ *${key}* = ${value}`);
}

// DEL
if (args[0] === 'del' && args.length >= 2) {
  const key = args[1].toUpperCase();
  delete configVars[key];
  fs.writeFileSync(varsFile, JSON.stringify(configVars, null, 2));
  return sendTrackedMessage(sock, remoteJid, `🗑️ *${key}* deleted.`);
}

return sendTrackedMessage(sock, remoteJid, `Usage:\n${botInfo.prefix}vars\n${botInfo.prefix}vars set <KEY> <value>\n${botInfo.prefix}vars del <KEY>\n\nSystem keys: PREFIX, SUDO`);

