const arg = argumentName ? argumentName.toLowerCase() : '';
const fs = require('fs');
const rPath = require('path');
const cfgPath = rPath.resolve(process.cwd(), 'antidel.json');

const selfJid = sock.user?.id.split(':')[0] + '@s.whatsapp.net';
const defaultTarget = (botInfo.permissions.numbers[0] ? botInfo.permissions.numbers[0] + '@s.whatsapp.net' : null) || selfJid;

let cfg = { enabled: true, target: defaultTarget };
try {
  if (fs.existsSync(cfgPath)) {
    const parsed = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
    // Only apply target from file if it's a valid non-null string
    cfg.enabled = typeof parsed.enabled === 'boolean' ? parsed.enabled : cfg.enabled;
    if (typeof parsed.target === 'string' && parsed.target.includes('@')) cfg.target = parsed.target;
  }
} catch(e) {}

if (arg === 'on') {
  cfg.enabled = true;
  fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2));
  return sendTrackedMessage(sock, remoteJid, `✅ Anti-Delete *ON* — forwarding to ${cfg.target}`);
} else if (arg === 'off') {
  cfg.enabled = false;
  fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2));
  return sendTrackedMessage(sock, remoteJid, '❌ Anti-Delete *OFF*');
} else if (arg === 'target' || arg === 'set') {
  // +antidel target +2347041029093
  const rawText = msg.message?.conversation || msg.message?.extendedTextMessage?.text || '';
  const parts = rawText.trim().split(/\s+/);
  const numArg = parts[2];
  if (numArg) {
    const num = numArg.replace(/\D/g, '');
    cfg.target = num + '@s.whatsapp.net';
    fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2));
    return sendTrackedMessage(sock, remoteJid, `✅ Anti-Delete target set to *+${num}*`);
  }
}

return sendTrackedMessage(sock, remoteJid, `*Anti-Delete Status*\nEnabled: ${cfg.enabled ? 'ON ✅' : 'OFF ❌'}\nTarget: ${cfg.target}\n\nUsage:\n${botInfo.prefix}antidel on | off\n${botInfo.prefix}antidel target +countrycodeNumber`);
